{
  "items": [
    {
      "name": "single_le_finsum",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_7} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] (i : α)\n  {f : α → M}, (Function.support f).Finite → (∀ (j : α), 0 ≤ f j) → f i ≤ ∑ᶠ (j : α), f j"
    },
    {
      "name": "Finset.sum_le_univ_sum_of_nonneg",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {N : Type u_5} [inst : AddCommMonoid N] [inst_1 : PartialOrder N] {f : ι → N} [AddLeftMono N]\n  [inst_3 : Fintype ι] {s : Finset ι}, (∀ (x : ι), 0 ≤ f x) → ∑ x ∈ s, f x ≤ ∑ x, f x"
    },
    {
      "name": "Finset.sum_nonneg",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {N : Type u_5} [inst : AddCommMonoid N] [inst_1 : PartialOrder N] {f : ι → N} {s : Finset ι}\n  [AddLeftMono N], (∀ i ∈ s, 0 ≤ f i) → 0 ≤ ∑ i ∈ s, f i"
    },
    {
      "name": "finsum_nonneg",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Sort u_4} {M : Type u_7} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {f : α → M},\n  (∀ (i : α), 0 ≤ f i) → 0 ≤ ∑ᶠ (i : α), f i"
    },
    {
      "name": "sum_le_hasSum",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Order",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_3} {L : SummationFilter ι} [inst : AddCommMonoid α] [inst_1 : PartialOrder α]\n  [IsOrderedAddMonoid α] [inst_3 : TopologicalSpace α] [OrderClosedTopology α] {f : ι → α} {a : α} [L.NeBot] [L.LeAtTop]\n  (s : Finset ι), (∀ i ∉ s, 0 ≤ f i) → HasSum f a L → ∑ i ∈ s, f i ≤ a"
    },
    {
      "name": "Fintype.sum_nonneg",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} [inst : Fintype ι] [inst_1 : AddCommMonoid M] [inst_2 : PartialOrder M] [AddLeftMono M]\n  {f : ι → M}, 0 ≤ f → 0 ≤ ∑ i, f i"
    },
    {
      "name": "ENNReal.tsum_le_tsum",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.ENNReal",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {f g : α → ENNReal}, (∀ (a : α), f a ≤ g a) → ∑' (a : α), f a ≤ ∑' (a : α), g a"
    },
    {
      "name": "ENNReal.lt_top_of_tsum_ne_top",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.ENNReal",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {a : α → ENNReal}, ∑' (i : α), a i ≠ ⊤ → ∀ (j : α), a j < ⊤"
    }
  ]
}
